-- Singapore milestone translations (ES/DE/FR)

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-first-peppol-2018', 'es', 'Singapur se convierte en la primera Autoridad Peppol fuera de Europa', 'Un hito temprano importante que establece el papel de Singapur en el ecosistema Peppol mucho antes de cualquier mandato de GST.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-first-peppol-2018', 'de', 'Singapur wird die erste Peppol-Autorität außerhalb Europas', 'Ein bedeutender früher Meilenstein, der Singapurs Rolle im Peppol-Ökosystem lange vor jedem GST-Mandat etabliert.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-first-peppol-2018', 'fr', 'Singapour devient la première autorité Peppol hors d''Europe', 'Une étape précoce importante établissant le rôle de Singapour dans l''écosystème Peppol bien avant tout mandat GST.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-invoicenow-launch-2019', 'es', 'Se lanza InvoiceNow', 'La IMDA introduce la red nacional de facturación electrónica de Singapur, basada en Peppol, para el intercambio voluntario de facturas estructuradas tanto en B2B como en B2G.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-invoicenow-launch-2019', 'de', 'InvoiceNow startet', 'Die IMDA führt Singapurs nationales E-Rechnungsnetzwerk ein, basierend auf Peppol, für den freiwilligen strukturierten Rechnungsaustausch sowohl im B2B- als auch im B2G-Bereich.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-invoicenow-launch-2019', 'fr', 'Lancement d''InvoiceNow', 'L''IMDA introduit le réseau national de facturation électronique de Singapour, basé sur Peppol, pour l''échange volontaire de factures structurées à la fois en B2B et en B2G.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-b2g-channel-2020', 'es', 'InvoiceNow se añade como canal B2G', 'La contratación pública gana InvoiceNow como canal de envío preferido para los proveedores.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-b2g-channel-2020', 'de', 'InvoiceNow als B2G-Kanal hinzugefügt', 'Die öffentliche Beschaffung erhält InvoiceNow als bevorzugten Übermittlungskanal für Lieferanten.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-b2g-channel-2020', 'fr', 'InvoiceNow ajouté comme canal B2G', 'Les marchés publics gagnent InvoiceNow comme canal de soumission privilégié pour les fournisseurs.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-voluntary-phase-2025', 'es', 'Comienza la fase voluntaria del Requisito GST InvoiceNow', 'Las empresas registradas en el GST existentes pueden enviar voluntariamente datos de facturas a la IRAS a través de InvoiceNow, antes de cualquier obligación obligatoria.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-voluntary-phase-2025', 'de', 'Freiwillige Phase der GST-InvoiceNow-Anforderung beginnt', 'Bestehende GST-registrierte Unternehmen können Rechnungsdaten freiwillig über InvoiceNow an die IRAS übermitteln, noch vor jeder verpflichtenden Vorgabe.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-voluntary-phase-2025', 'fr', 'Début de la phase volontaire de l''exigence GST InvoiceNow', 'Les entreprises déjà enregistrées à la GST peuvent soumettre volontairement des données de facturation à l''IRAS via InvoiceNow, avant toute obligation contraignante.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-voluntary2025', 'es', 'GST InvoiceNow obligatorio — nuevos registrantes voluntarios de GST (dentro de los 6 meses posteriores a la constitución)', 'La primera fase obligatoria de GST InvoiceNow requería que las empresas que se registraran voluntariamente para el GST dentro de los seis meses posteriores a su constitución transmitieran datos de facturas a la IRAS a través de la red InvoiceNow basada en Peppol.', '["Nuevos registrantes de GST calificados: configuren una Solución Lista para InvoiceNow y un ID Peppol en el momento del registro"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-voluntary2025', 'de', 'GST InvoiceNow verpflichtend — neue freiwillige GST-Registranten (innerhalb von 6 Monaten nach Gründung)', 'Die erste verpflichtende Phase von GST InvoiceNow verlangte von Unternehmen, die sich innerhalb von sechs Monaten nach ihrer Gründung freiwillig für die GST registrierten, Rechnungsdaten über das Peppol-basierte InvoiceNow-Netzwerk an die IRAS zu übermitteln.', '["Neue qualifizierte GST-Registranten: Richten Sie zum Zeitpunkt der Registrierung eine InvoiceNow-Ready-Lösung und eine Peppol-ID ein"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-voluntary2025', 'fr', 'GST InvoiceNow obligatoire — nouveaux inscrits volontaires à la GST (dans les 6 mois suivant la constitution)', 'La première phase obligatoire de GST InvoiceNow exigeait des entreprises s''inscrivant volontairement à la GST dans les six mois suivant leur constitution qu''elles transmettent les données de facturation à l''IRAS via le réseau InvoiceNow basé sur Peppol.', '["Nouveaux inscrits GST qualifiés : mettez en place une solution prête pour InvoiceNow et un identifiant Peppol dès l''inscription"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-allvoluntary', 'es', 'El mandato se extiende a todos los nuevos registrantes voluntarios de GST', 'Todos los nuevos registrantes voluntarios de GST, independientemente de la fecha de constitución o la estructura empresarial, deben adoptar InvoiceNow como condición para el registro de GST.', '["Incorpore la configuración de InvoiceNow en su solicitud de registro de GST a partir de esta fecha", "Use la calculadora de fecha de implementación de la IRAS si no está seguro de qué fase se aplica a usted"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-allvoluntary', 'de', 'Das Mandat wird auf alle neuen freiwilligen GST-Registranten ausgeweitet', 'Alle neuen freiwilligen GST-Registranten müssen unabhängig vom Gründungsdatum oder der Unternehmensstruktur InvoiceNow als Voraussetzung für die GST-Registrierung einführen.', '["Berücksichtigen Sie die InvoiceNow-Einrichtung ab diesem Datum in Ihrem GST-Registrierungsantrag", "Nutzen Sie den Implementierungsdatumsrechner der IRAS, falls unsicher, welche Phase für Sie gilt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-allvoluntary', 'fr', 'Le mandat s''étend à tous les nouveaux inscrits volontaires à la GST', 'Tous les nouveaux inscrits volontaires à la GST, quelle que soit leur date de constitution ou leur structure d''entreprise, doivent adopter InvoiceNow comme condition d''inscription à la GST.', '["Intégrez la mise en place d''InvoiceNow dans votre demande d''inscription à la GST à partir de cette date", "Utilisez le calculateur de date de mise en œuvre de l''IRAS en cas de doute sur la phase applicable"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-existing2028', 'es', 'Comienza el despliegue por fases para empresas ya registradas en el GST', 'Las empresas ya registradas en el GST comienzan a incorporarse a GST InvoiceNow según un calendario por fases que se extiende hasta la adopción completa en 2031. La IRAS notificará a las empresas afectadas su fecha específica durante 2026.', '["Use la Calculadora de Fecha de Implementación de GST InvoiceNow de la IRAS para determinar su fecha aplicable", "Esté atento a la notificación directa de la IRAS (prevista para mediados de 2026)"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-existing2028', 'de', 'Stufenweiser Rollout beginnt für bestehende GST-registrierte Unternehmen', 'Bestehende GST-registrierte Unternehmen werden schrittweise nach einem Zeitplan in GST InvoiceNow einbezogen, der bis zur vollständigen Einführung im Jahr 2031 läuft. Die IRAS benachrichtigt betroffene Unternehmen im Laufe des Jahres 2026 über ihr spezifisches Datum.', '["Verwenden Sie den GST-InvoiceNow-Implementierungsdatumsrechner der IRAS, um Ihr zutreffendes Datum zu bestimmen", "Achten Sie auf die direkte Benachrichtigung durch die IRAS (voraussichtlich Mitte 2026)"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-existing2028', 'fr', 'Début du déploiement échelonné pour les entreprises déjà enregistrées à la GST', 'Les entreprises déjà enregistrées à la GST commencent à être intégrées dans GST InvoiceNow selon un calendrier échelonné se poursuivant jusqu''à l''adoption complète en 2031. L''IRAS notifiera aux entreprises concernées leur date spécifique au cours de 2026.', '["Utilisez le calculateur de date de mise en œuvre GST InvoiceNow de l''IRAS pour déterminer votre date applicable", "Surveillez la notification directe de l''IRAS (attendue d''ici mi-2026)"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-phase-2029', 'es', 'Contribuyentes existentes, ventas anuales ≤ 1 millón S$', 'La extensión por fases continúa con la siguiente banda de facturación de empresas ya registradas en el GST que entran en el alcance.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-phase-2029', 'de', 'Bestehende Steuerpflichtige, Jahresumsatz ≤ 1 Mio. S$', 'Die stufenweise Ausweitung setzt sich mit der nächsten Umsatzband bestehender GST-registrierter Unternehmen fort, die in den Anwendungsbereich einbezogen werden.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-phase-2029', 'fr', 'Contribuables existants, ventes annuelles ≤ 1 million S$', 'L''extension échelonnée se poursuit avec la tranche de chiffre d''affaires suivante des entreprises déjà enregistrées à la GST entrant dans le champ d''application.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-phase-2030', 'es', 'Contribuyentes existentes, ventas anuales ≤ 4 millones S$', 'La extensión por fases continúa con la siguiente banda de facturación de empresas ya registradas en el GST que entran en el alcance.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-phase-2030', 'de', 'Bestehende Steuerpflichtige, Jahresumsatz ≤ 4 Mio. S$', 'Die stufenweise Ausweitung setzt sich mit der nächsten Umsatzband bestehender GST-registrierter Unternehmen fort, die in den Anwendungsbereich einbezogen werden.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-phase-2030', 'fr', 'Contribuables existants, ventes annuelles ≤ 4 millions S$', 'L''extension échelonnée se poursuit avec la tranche de chiffre d''affaires suivante des entreprises déjà enregistrées à la GST entrant dans le champ d''application.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-full2031', 'es', 'Adopción completa — todas las empresas registradas en el GST', 'Para esta fecha, cada empresa registrada en el GST en Singapur, incluidas las grandes empresas multinacionales, debe transmitir datos de facturas a través de InvoiceNow.', '["Planifique la integración con suficiente antelación — hay subvenciones gubernamentales transitorias disponibles para apoyar la adopción"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-full2031', 'de', 'Vollständige Einführung — alle GST-registrierten Unternehmen', 'Bis zu diesem Datum muss jedes GST-registrierte Unternehmen in Singapur, einschließlich großer multinationaler Konzerne, Rechnungsdaten über InvoiceNow übermitteln.', '["Planen Sie die Integration weit im Voraus — für die Einführung stehen befristete staatliche Zuschüsse zur Verfügung"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('sg-full2031', 'fr', 'Adoption complète — toutes les entreprises enregistrées à la GST', 'D''ici cette date, chaque entreprise enregistrée à la GST à Singapour, y compris les grandes multinationales, doit transmettre des données de facturation via InvoiceNow.', '["Planifiez l''intégration bien à l''avance — des subventions gouvernementales transitoires sont disponibles pour soutenir l''adoption"]');
